/** 📐️ STEP typed header, graph and IEEE fields remain independently queryable. */
import {Database} from "bun:sqlite";
import {expect,test} from "bun:test";
import f from "../../🧫️fixtures/🪶️sqlite/🔣️.json";
import type {StepSnapshot,StepValue} from "../../🟦️.ts";
import {STEP_SQLITE_SCHEMA,stepSnapshotToSqliteDatabase,stepSnapshotFromSqliteDatabase} from "../../🪶️sqlite/🟦️.ts";
import {exportSqliteDatabase,importSqliteDatabase} from "@semio-tech/framework";
import type {StepArtifact} from "../../../🟦️.ts";
import type {StepDiff} from "../../../🔺️diff/🟦️.ts";
import type {StepMutation} from "../../../🧬️mutations/🟦️.ts";
function fixture():StepSnapshot{return{schema:f.schema,header:structuredClone(f.header),entities:[{id:BigInt(f.instanceWords[0]!),name:"PRIMARY",args:["unset","derived",{integer:BigInt(f.integerWords[0]!)},{integer:BigInt(f.integerWords[1]!)},...f.binary64Words.map(word=>({real:{bits:BigInt("0x"+word)}})),{string:"English Deutsch\u0000文"},{enum:"UNKNOWN"},{reference:BigInt(f.instanceWords[1]!)},{aggregate:[]},{typedValue:{typeName:"LENGTH_MEASURE",value:{aggregate:[{integer:1n},{string:""}]}}}],complex:[{name:"COMPLEX",args:[{reference:1n},{aggregate:["derived","unset"]}]}]},{id:BigInt(f.instanceWords[1]!),name:"TARGET",args:[{reference:1n}],complex:[]}]};}
test("STEP owned variant widths, cycles and large scalar preallocation controls",async()=>{
  for(const value of [{integer:1n,enum:"X"},{integer:1n<<63n},{reference:1n<<64n},{real:{bits:1n<<64n}}]){const snapshot=fixture();snapshot.entities[0]!.args=[value as StepValue];await expect(stepSnapshotToSqliteDatabase(snapshot)).rejects.toThrow();}
  const cycle:{aggregate:StepValue[]}={aggregate:[]};cycle.aggregate.push(cycle);const cyclic=fixture();cyclic.entities[0]!.args=[cycle];await expect(stepSnapshotToSqliteDatabase(cyclic)).rejects.toThrow();
  const snapshot=fixture();snapshot.entities[0]!.args=[{string:"文".repeat(40000)}];await expect(stepSnapshotToSqliteDatabase(snapshot,{maxValueBytes:4096})).rejects.toThrow();const controller=new AbortController();let completed=0;await expect(stepSnapshotToSqliteDatabase(snapshot,{signal:controller.signal,onProgress(progress){if(progress.phase==="projectSnapshot"&&progress.completed>0){completed=progress.completed;controller.abort();}}})).rejects.toThrow();expect(completed).toBeGreaterThan(0);
});

test("STEP native ownership limits and nonfinite preflight use explicit independent roles",async()=>{
 const vector=await Bun.file(new URL("../../🧫️fixtures/🪶️sqlite/💰️backing/🔣️.json",import.meta.url)).json();
 expect(vector.nativeRoles).toEqual({owned:"maxAllocationBytes",semantic:"maxValueBytes",preflight:"paidFrontiersOnly",nonfinite:"retainedBinary64"});
 const db=new Database(":memory:");
 try{db.exec("CREATE TABLE requests(bytes INTEGER NOT NULL CHECK(bytes>=0));");for(const request of vector.ledger.requests)db.run("INSERT INTO requests VALUES(?)",[request]);const sum=(db.query("SELECT sum(bytes) AS spent FROM requests").get()as{spent:number}).spent;expect(sum).toBe(vector.ledger.exact);expect(sum>vector.ledger.refused).toBe(true);const words=new Database(":memory:");try{words.exec("CREATE TABLE literal(bits TEXT NOT NULL, class TEXT NOT NULL);");vector.literal.binary64Words.forEach((word:string,index:number)=>words.run("INSERT INTO literal VALUES(?,?)",[word,vector.literal.binary64Classes[index]]));expect(words.query("SELECT count(*) AS retained FROM literal WHERE class='nan'").get()).toEqual({retained:2});}finally{words.close();}}finally{db.close();}
});

test("STEP independent complete header/entity/value joins and edited scalar",async()=>{
  expect(STEP_SQLITE_SCHEMA).toBe(await Bun.file(new URL("../../🪶️sqlite/🗄️.sql",import.meta.url)).text());
  const input=fixture(),db=Database.deserialize(await exportSqliteDatabase(await stepSnapshotToSqliteDatabase(input)));
  try{expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(db.query("SELECT content FROM step_description ORDER BY ordinal").all()).toEqual(f.header.fileDescription.description.map(content=>({content})));expect(db.query("SELECT COUNT(*) count FROM step_complex_type").get()).toEqual({count:1});const kinds=db.query("SELECT kind FROM step_value GROUP BY kind ORDER BY kind").all() as {kind:string}[];expect(kinds.map(v=>v.kind)).toEqual([...f.valueKinds].sort());expect(db.query(f.queries.references).all()).toEqual([{reference_instance_id:f.instanceWords[1],instance_id:f.instanceWords[1]},{reference_instance_id:"1",instance_id:"1"},{reference_instance_id:"1",instance_id:"1"}]);expect(await stepSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(input);db.query("UPDATE step_header SET authorization='independent edit'").run();const expected=fixture();expected.header.fileName.authorization="independent edit";expect(await stepSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(expected);}finally{db.close();}
});
test("STEP structural ownership, reference identities, wide words and controls",async()=>{
  const input=fixture(),original=await stepSnapshotToSqliteDatabase(input);
  for(const mutate of[(d:any)=>d.tables.find((t:any)=>t.name==="step_argument").rows[0].values[4]=999n,(d:any)=>d.tables.find((t:any)=>t.name==="step_value").rows.find((r:any)=>r.values[1]==="reference").values[6]="00",(d:any)=>d.tables.find((t:any)=>t.name==="step_entity").rows[1].values[3]="1",(d:any)=>d.tables.find((t:any)=>t.name==="step_argument").rows[0].values[2]=1n,(d:any)=>d.tables.find((t:any)=>t.name==="step_description").rows[0].values[2]=7n,(d:any)=>d.tables.find((t:any)=>t.name==="step_value").rows.find((r:any)=>r.values[1]==="real").values[9]="nan"]){const changed=structuredClone(original);mutate(changed);expect(stepSnapshotFromSqliteDatabase(changed)).rejects.toThrow();}
  expect(stepSnapshotToSqliteDatabase(input,{maxRows:1})).rejects.toThrow();expect(stepSnapshotFromSqliteDatabase(original,{maxValueBytes:1})).rejects.toThrow();const controller=new AbortController();controller.abort();expect(stepSnapshotToSqliteDatabase(input,{signal:controller.signal})).rejects.toThrow();let depth:StepValue="unset";for(let i=0;i<2000;i++)depth={aggregate:[depth]};const deep=fixture();deep.entities[0]!.args=[depth];const restored=await stepSnapshotFromSqliteDatabase(await stepSnapshotToSqliteDatabase(deep));let cursor=restored.entities[0]!.args[0]!;for(let i=0;i<2000;i++){if(typeof cursor!=="object"||!("aggregate" in cursor))throw Error("deep STEP value");cursor=cursor.aggregate[0]!;}expect(cursor).toBe("unset");
},20000);
test("STEP artifact and command consumers own exact scalar widths",()=>{const artifact:StepArtifact=fixture(),id=BigInt(f.instanceWords[1]!),value:StepValue={real:{bits:BigInt("0x"+f.binary64Words[6]!)}};const diff:StepDiff={entities:{removed:[id],modified:[{id,diff:{args:{modified:[{index:0,value}]}}}]}};const command:StepMutation={mutation:"setEntityArg",id,argIndex:0,value};expect(artifact.entities[1]!.id).toBe(id);expect(diff.entities!.removed![0]).toBe(id);expect(diff.entities!.modified![0]!.id).toBe(id);expect(command.id).toBe(id);if(typeof command.value!=="object"||!("real" in command.value))throw Error("fixture owned real");expect(command.value.real.bits).toBe(BigInt("0x"+f.binary64Words[6]!));});

test("STEP closed backing contracts separate paid frontiers from exact literal state",async()=>{
 const {default:Ajv}=await import("ajv/dist/2020.js");const vector=await Bun.file(new URL("../../🧫️fixtures/🪶️sqlite/💰️backing/🔣️.json",import.meta.url)).json();const schema=await Bun.file(new URL("../../🧫️fixtures/🪶️sqlite/💰️backing/🧬️schema/🔣️.json",import.meta.url)).json();const validate=new Ajv({strict:true}).compile(schema);
 expect(validate(vector)).toBe(true);expect(validate({...vector,unknown:0})).toBe(false);expect(validate({...vector,forecast:"paidAsBacking"})).toBe(false);expect(validate({...vector,stages:vector.stages.slice(1)})).toBe(false);expect(validate({...vector,limits:{...vector.limits,backing:"maxValueBytes"}})).toBe(false);
 const db=new Database(":memory:");try{db.run("CREATE TABLE admission(request INTEGER NOT NULL CHECK(request>=0),retired INTEGER NOT NULL)");for(const request of vector.ledger.requests)db.run("INSERT INTO admission VALUES(?,1)",[request]);expect(db.query("SELECT sum(request) AS spent FROM admission").get()).toEqual({spent:vector.ledger.expectedSpent});expect(vector.ledger.exact).toBe(vector.ledger.expectedSpent);expect(vector.ledger.refused).toBe(vector.ledger.expectedSpent-1);const text=vector.literal.unit.repeat(vector.literal.repeat);expect(db.query("SELECT length(CAST(? AS BLOB)) AS bytes").get(text)).toEqual({bytes:new TextEncoder().encode(text).length});expect(Buffer.byteLength(text,"utf8")).toBe(new TextEncoder().encode(text).length);const ddl=await Bun.file(new URL("../../🪶️sqlite/🗄️.sql",import.meta.url)).text();db.exec(ddl);expect(db.query("SELECT count(*) AS count FROM sqlite_schema WHERE type='table' AND name LIKE 'step_%'").get()).toEqual({count:vector.relations.tableCount});expect(BigInt(vector.literal.instanceWord)).toBe((1n<<64n)-1n);for(const [index,word] of vector.literal.binary64Words.entries()){const bits=BigInt("0x"+word),view=new DataView(new ArrayBuffer(8));view.setBigUint64(0,bits,true);const value=view.getFloat64(0,true);expect(view.getBigUint64(0,true)).toBe(bits);expect(Number.isNaN(value)?"nan":value===Infinity?"positiveInfinity":value===-Infinity?"negativeInfinity":Object.is(value,-0)?"negativeZero":"finite").toBe(vector.literal.binary64Classes[index]);}expect(vector.stages).toEqual(["nativeInput","nativeFields","preflightFrontier","projectionFrontier","relationIndex","reconstructionFields","valueOwnership"]);}finally{db.close()}
});

test("STEP borrowed preflight pays each complete scratch replacement independently of its bound",async()=>{
